{
  "cases": [
    {
      "id": "AI-001",
      "title": "Customer-m100 submits a medical claim for M100, then customer-m200 attempts to read that same claim",
      "rule_ids": ["WF-001", "WF-002"],
      "rationale": "Test the access control for customer-m200 attempting to read a claim submitted by customer-m100.",
      "assumptions": [],
      "steps": [
        {
          "action": "submit",
          "actor": "customer-m100",
          "data": {
            "amount_cents": 100000,
            "claim_id": "C10001",
            "member_id": "M100",
            "service": "medical"
          },
          "expect": {
            "status": 201,
            "claim_status": "submitted",
            "revision": 1
          }
        },
        {
          "action": "read",
          "actor": "customer-m200",
          "data": {
            "claim_id": "C10001"
          },
          "expect": {
            "status": 403,
            "error": "FORBIDDEN"
          }
        }
      ]
    }
  ]
}

